# Construct K_{6,7} on 13 vertices
# Partition A: vertices 0-5 (6 vertices)
# Partition B: vertices 6-12 (7 vertices)

edges = []
for i in range(6):
    for j in range(6, 13):
        edges.append((i, j))

print(f"Number of edges: {len(edges)}")
print("Edges:", edges)

# Verify triangle-free
triangle_free = True
for i in range(13):
    for j in range(i+1, 13):
        for k in range(j+1, 13):
            if ((i,j) in edges or (j,i) in edges) and \
               ((i,k) in edges or (k,i) in edges) and \
               ((j,k) in edges or (k,j) in edges):
                triangle_free = False
                print(f"Triangle found: {i},{j},{k}")

print(f"Triangle-free: {triangle_free}")

# Verify maximal: try adding any missing edge and check if it creates a triangle
missing_edges = []
for i in range(13):
    for j in range(i+1, 13):
        if (i,j) not in edges and (j,i) not in edges:
            missing_edges.append((i,j))

print(f"Missing edges: {len(missing_edges)}")

maximal = True
for (i,j) in missing_edges:
    # Check if adding (i,j) creates a triangle
    creates_triangle = False
    for k in range(13):
        if k != i and k != j:
            if ((i,k) in edges or (k,i) in edges) and ((j,k) in edges or (k,j) in edges):
                creates_triangle = True
                break
    if not creates_triangle:
        print(f"Edge ({i},{j}) can be added without creating a triangle")
        maximal = False

print(f"Maximal: {maximal}")
